UPDATE `mor_prodotti` SET `description` = 'Impero Romano, <b>MASSENZIO</b>, 306-312 d.C., <b>FOLLIS</b>, Emissione: <b>309-312 d.C.</b>, <b>D</b>/ IMP C MAXENTIVS P F AVG, <b>testa laureata</b> a destra, <b>R</b>/ AETERNITAS AVG N / MOSTQ, <b>i Dioscuri in piedi uno di fronte all</b<\'<b>altro</b>, <b>ciascuno regge un lungo scettro e le briglie del proprio cavallo</b>, Zecca di <b>Ostia</b>*, Rif. bibl. <b>R.I.C.</b>, <b>35</b>; Cohen, 5; Metallo: <b>AE</b>, gr. 6,82, (MR26910), Diam.: mm. 25,65, <b>SPL</b>

<br><br>

<b>*</b> L\'antica città di Ostia fu fondata nel corso del IV secolo a.C. come <b>accampamento militare</b> e sviluppata nel corso dell\'età imperiale romana come <b>centro commerciale portuale</b>, strettamente legato all\'<b>approvvigionamento del grano nella capitale</b>. A causa dell\'insufficienza del porto fluviale <b>Claudio</b> iniziò nel 42 d.C. la <b>costruzione di un porto artificiale</b> più a nord, collegato al Tevere da un <b>canale artificiale</b> e dotato di un <b>faro</b>; un secondo <b>porto esagonale</b> venne costruito tra il 106 e il 113 sotto <b>Traiano</b>, i cui resti si trovavano nella proprietà privata dei <b>Duchi Sforza Cesarini</b>. All\'epoca del suo </b>massimo sviluppo</b> la città romana di Ostia raggiunse i <b>75</b>.<b>000 abitanti</b>, ma declinò con la <b>crisi del III secolo</b>. Ebbe una <b>ripresa nel IV secolo come sede residenziale</b>, mentre <b>le attività commerciali e amministrative</b> si erano spostate nella città di Porto.' WHERE `entity_id` = 17264;
-- entity_id=17334 description
UPDATE `mor_prodotti` SET `description` = 'Impero Romano, <b>GIOVIANO</b>, 363-364 d.C., <b>MAIORINA</b>, Emissione: <b>363-364 d.C.</b>, <b>D</b>/ D N IOVIANVS P F P P AVG, <b>busto diademato con paludamento e corazza</b> a destra, <b>R</b>/ VICTORIA ROMANORVM / TESA, <b>l</b>\'<b>imperatore in abiti militari</b> stante di fronte volto a destra <b>con labaro con cristogramma</b> nella mano destra <b>e globo niceforo</b> nella sinistra, Zecca di <b>Tessalonica</b>*, Rif. bibl. <b>R.I.C.</b>, <b>235</b>/<b>S</b>; Cohen, 23/Fr.8; Metallo: <b>AE</b>, gr. 8,77, (MR26864), Diam.: mm. 26,68, <b>qSPL</b>, (<b>R</b>)

<br><br>

Ex <b>Ponterio</b> (<b>14</b>-<b>15</b>/<b>01</b>/<b>05</b>) n. 1; ex <b>Busso Peus 395</b> n. 389.

<br><br>

<b>*</b> Tessalonìca di Macedonia (attualmente in Grecia e chiamata in italiano <b<Salonicco</b>) fu <b>fondata</b> all\'incirca nel 315 a.C. <b>da Cassandro</b>, Re dei Macedoni. Nel 146 a.C. fu <b>conquistata dai Romani</b> e fece parte della <b>provincia romana di Macedonia</b>.' WHERE `entity_id` = 17334;
-- entity_id=17658 description
UPDATE `mor_prodotti` SET `description` = 'Impero Romano, <b>Lycia</b>-<b>Pamphylia</b>, <b>GIULIA MESA</b>, Sorella di Giulia Domna, 218-222 d.C., <b>GRANDE BRONZO</b>, Emissione: <b>218</b>-<b>222 d.C.</b>, <b>D</b>/ <b>busto diademato e ammantato</b> a d., <b>R</b>/ <b>Serapide seduto sul trono</b> a s., <b>tiene lungo scettro e stende la mano</b> destra <b>su Cerbero seduto ai suoi piedi</b>, a sinistra; davanti a lui, <b>Iside in piedi</b> a destra, <b>con in mano il sistro</b>; dietro di lui, <b>Demetra</b> (?) <b>in piedi</b> frontalmente, guardando a sinistra, <b>con in mano una lunga torcia</b> (?), Zecca di <b>Aspendus</b> (<b>Lycia</b>-<b>Pamphylia</b>), Rif. bibl. <b>SNG France</b>, <b>171</b>; R.P.C., 6265 temporaneo; Metallo: <b>AE</b>, gr. 27,17, (MR25948), Diam.: mm. 34,56, MB, (<b>RR</b>)

