UPDATE `mor_prodotti` SET `description` = '<b>Sicilia</b>, <b>MAMERTINI</b>*, 220-200 a.C., <b>PENTONKIA</b>, Emissione: <b>220</b>-<b>200 a.C.</b>, <b>D</b>/ <b>testa laureata di Zeus</b> a d., dietro la testa <b>una clava</b>, <b>R</b>/ MAMEPTINΩN, <b>guerriero</b> a d., <b>con asta</b> nella destra <b>e scudo</b> nella sinistra; nel campo, in basso a d.: Π, Zecca di <b>Messana</b>, Rif. bibl. <b>Buceti</b>, <b>41</b>; Metallo: <b>AE</b>, gr. 11,38, (MG20041), Diam.: mm. 21,63, BB

<br><br>

Tutte le monete, medaglie e banconote <b>vendute dalla Moruzzi Numismatica</b> di Roma sono <b>garantite autentiche senza limite di tempo</b> e accompagnate dal “<b>Cartellino</b>” con <b>QR code</b> e dal “<b>Certificato fotografico di Autenticità e Provenienza</b>”.

<br><br>

<b>*</b> <b>Mercenarî italici</b>, per la maggior parte <b>campani</b<, del tiranno siracusano <b>Agatocle</b>; derivato dal <b>nome osco del dio della guerra</b> (Mamers "Marte"). Dopo la <b>morte di Agatocle</b> (289 a.C.) il <b>governo repubblicano</b> instauratosi in Siracusa dovette <b>venire a patti coi numerosi mercenari</b> del disciolto esercito del tiranno, a ciascuno di essi <b>fu promessa la cittadinanza e un lotto di terre</b>. Ma, sopraggiunte presto <b>discordie fra gli antichi e i nuovi cittadini di Siracusa</b>, i Mamertini s\'indussero ad <b>accettare denaro in cambio delle terre ricevute e ad abbandonare la città</b>. Sulla via del <b>ritorno</b>, però, quando già stavano per <b<salpare dalla Sicilia verso la penisola</b>, riuscirono a <b>impadronirsi a tradimento</b> della città <b>di Messina</b>: uccisi tutti gli uomini adulti, la città, le donne, i beni di essi vennero in <b>possesso dei Mamertini</b>. Ben presto <b>i nuovi padroni di Messina ebbero sparso il terrore in tutta la regione orientale dell</b>\'<b>isola a nord di Siracusa</b>: le <b>campagne</b> erano sistematicamente saccheggiate, alcune <b>città</b> furono prese o distrutte, altre sottoposte a <b>tributo</b> (circa 283 a.C.).' WHERE `entity_id` = 17794;
