UPDATE `mor_prodotti` SET `description` = '<b>Impero Romano</b>, <b>POSTUMO</b>, 259-268 d.C., <b>ANTONINIANO</b>, Emissione: <b>259</b>-<b>268 d.C.</b, <b>D</b>/ IMP C POSTVMVS P F AVG, <b>busto radiato con paludamento</b> a destra, <b>R</b>/ MONETA AVG, <b>la Moneta</b> stante a sinistra <b>con bilancia e cornucopia</b>, Zecca di <b>Lugdunum</b>*, Rif. bibl. <b>R.I.C.</b>, <b>75</b>; Cohen, 199; Metallo: <b>AR</b>, gr. 4,11, (MR24748), Diam.: mm. 20,66, <b>SPL</b>

<br><br>

Tutte le monete, medaglie e banconote <b>vendute dalla Moruzzi Numismatica</b> di Roma sono <b>garantite autentiche senza limite di tempo</b> e accompagnate dal “<b>Cartellino</b>” con <b>QR code</b> e dal “<b>Certificato fotografico di Autenticità e Provenienza</b>”.

<br><br>

<b>*</b> Odierna <b>Lione</b>, città della Francia capoluogo del dipartimento del Rodano, fu <b>fondata sul luogo di un villaggio celtico da Lucio Munazio Planco</b> nel 43 a.C. Divenne subito <b>capitale</b>, col nome di Lugdunum, <b>della Gallia Lugdunensis</b> e centro economico e militare di grande importanza. Nel 12 a.C. <b>Druso vi inaugurò un</b>’<b>ara di Roma e Augusto</b> presso cui, ogni anno, si riuniva l’<b>assemblea dei delegati delle tre Gallie</b>. La città fu <b>saccheggiata nel 197 dai soldati di Settimio Severo</b>, vittoriosi su Albino. Fu <b>sede di una delle più antiche comunità cristiane d</b>’<b>Occidente</b> e fu teatro di una <b>violenta persecuzione sotto Marco Aurelio</b> (177).' WHERE `entity_id` = 18148;
-- entity_id=18153 description
UPDATE `mor_prodotti` SET `description` = '<b>Sicilia</b>, <b>HIMERA</b>, <b>HEMILITRON</b>, Emissione: <b>413</b>-<b>408 a.C.</b>, <b>D</b>/ <b>testa di ninfa</b> a s., <b>con collana</b>, <b>capelli raccolti nella sphendone</b>; davanti al viso: <b>sei globetti</b> (••••••); dietro la nuca: <b>IM</b>, <b>R</b>/ <b>sei globetti</b> (••••••) <b>in corona di alloro</b>, Zecca di <b>Himera</b>*, Rif. bibl. SNG Dan., 320; <b>Buceti</b>, <b>114</b>; Metallo: <b>AE</b>, gr. 3,18, (MG20156), Diam.: mm. 16,01, <b>SPL</b>

<br><br>

Tutte le monete, medaglie e banconote <b>vendute dalla Moruzzi Numismatica</b> di Roma sono <b>garantite autentiche senza limite di tempo</b> e accompagnate dal “<b>Cartellino</b>” con <b>QR code</b> e dal “<b>Certificato fotografico di Autenticità e Provenienza</b>”.

<br><br>

<b>**</b> Secondo lo storico Tucidide, <b>Himera fu fondata</b> nel 648 a.C. <b>da coloni greci di origine calcidese e dorica provenienti da Zankle</b< (l’attuale Messina) <b>e da un gruppo di fuoriusciti politici di Siracusa</b>. La sua <b>ottima posizione naturale</b>, dove il fiume Imera incontra la pianura di Buonfornello, le <b>consentiva facili e veloci scambi commerciali</b>, divenendo un <b>nodo cruciale</b> e un’<b>importante via di collegamento della Sicilia centrale</b>. La città fu presa da <b<Terone</b>, tiranno di Agrigento nel 482 a.C., e la sua <b>popolazione deportata</b>. Dopo la fine della <b>dominazione</b> \'<b>Akragantina</b>\' nel 472 a.C., la città conobbe un <b>notevole sviluppo economico fino alla sua definitiva distruzione da parte delle forze cartaginesi</b> nel 408 a.C. <b>La sua popolazione</b>, che contava fino a 40.000 abitanti, <b>si rifugiò poi a Therma</b>.' WHERE `entity_id` = 18153;
-- entity_id=18158 description
