UPDATE `mor_prodotti` SET `description` = '<b>Stato Pontificio</b>, <b>BENEDETTO XV</b>, <b>Della Chiesa</b>, 1914-1922, <b>MEDAGLIA ANNUALE IN ARGENTO</b>, <b>Invocazione</b> alla <b>Regina Pacis</b> (preghiere per la pace), Emissione: <b>1916 AN II</b>, <b>D</b>/ BENEDICTVS • XV • PONT • MAX • A • II, <b>busto</b> con <b>berretto</b>, <b>mozzetta</b> e <b>stola</b> a s.; sotto: BIANCHI, <b>R</b>/ REGINA • PACIS ORA • PRO • NOBIS, il <b>Papa</b< con i <b>cinque continenti</b>, in <b>adorazione</b> alla <b>Beata Vergine</b> su <b>nubi</b>, che <b>porge</b> un <b>ramo</b> di <b>olivo</b>; in esergo: A MDCCCCXVI BIANCHI, <b>Opus Francesco Bianchi</b>, Rif. bibl. <b>Bart</b>., <b>E916</b>; Metallo: <b>AR</b>, gr. 42,44, (MP150406), Diam.: mm. 44,09, <b>FDC</b>, (NC)

