UPDATE `mor_prodotti` SET `description` = '<b>Stato Pontificio</b>, <b>ALESSANDRO VII</b>, <b>Chigi</b>, 1655-1667, <b>MEDAGLIA ANNUALE</b> IN <b>BRONZO</b>, La <b>Cattedra</b> di <b>San Pietro</b>, Emissione: <b>1662 AN VIII</b>, <b>D</b>/ ALEXANDER • VII PONT • MAX •, <b>busto</b> a s. con <b>triregno</b> e <b>piviale</b>; sul taglio spalla: G M •; sotto: AN • VIII, <b>R</b>/ PRIMA SEDES FIDEI REGVLA ECCLESIAE FVNDAMENTVM, la <b>Cattedra</b> di <b>San Pietro</b>, nell\'<b>abside</b> della <b>Basilica Vaticana</b>, Opus <b>Gaspare Morone</b>, Rif. bibl. Miselli, 600; <b>Bart</b>., <b>E662</b>; Metallo: <b>AE</b>, gr. 27,08, (MP153587), Diam.: mm. 42,15, <b>qFDC</b>, (<b>R</b>)

<br><br>

<b>Contorno</b>: perlinato.

<br><br>

<b>Medaglia annuale emessa</b> il <b>29 giugno 1662</b> per <b>ricordare</b> il <b>completamento</b> dell\'<b>altare</b> del <b>coro</b> della <b>Basilica Vaticana</b> con la <b>sistemazione</b> del "<b>Trono</b> di <b>San Pietro</b>", la <b>sedia</b> di <b>quercia</b>, <b>simbolo</b> della <b>successione apostolica</b> al <b>pontificato</b>. Questo <b>altare</b>, tra le <b>massime opere</b> del <b>Barocco</b>, <b>progettato</b> da <b>Gian Lorenzo Bernini</b> nella <b>parte absidale</b> della <b>Basilica</b> di <b>S. Pietro</b>, <b>raccoglie</b> al <b>suo interno</b> la <b>sedia episcopale sorretta</b> dai <b>Santi Agostino</b>, <b>Ambrogio</b>, <b>Atanasio</b> e <b<Giovanni Crisostomo</b>; <b>sopra</b> lo <b>scranno</b> gli <b>angeli sorreggono</b> la <b>tiara</b> e lo <b>Spirito Santo irraggia</b> tutta la <b>scena</b>. Anche la <b>presente medaglia</b> fu <b>disegnata</b> da <b>Gian Lorenzo Bernini</b> e <b>realizzata</b> dal <b>Morone</b>.

<br><br>

